import { env as getProcessEnv } from "../../platform/compat/process.js";
import { sanitizeTerminalDiagnosticText } from "../../errors/safe-diagnostics.js";
import { runWithRequestContext } from "../../platform/adapters/fs/veryfront/multi-project-adapter.js";
import { getEnv } from "../../platform/compat/process.js";
import { mergeInjectedWorkflowEnv } from "../../runs/runtime-env.js";
import { WorkflowClient } from "../api/workflow-client.js";
import { reconcileWorkflowRunControl } from "../runtime/workflow-run-control.js";
/** Return the immutable worker owner assigned to this isolated run execution. */
export function getRunExecutionWorkerId() {
    const executionId = getEnv("RUN_EXECUTION_ID");
    return executionId ? `run-execution:${executionId}` : undefined;
}
/**
 * Create an isolated executor with durable wait handling and no background timer.
 *
 * This executor serves one run and exits, so neither sweep belongs to it: both
 * exist to reclaim waits whose process is gone, which is the long-lived
 * client's job.
 */
export function createIsolatedWorkflowExecutor(backend, debug = false, stepExecutor) {
    const client = new WorkflowClient({
        backend,
        debug,
        executor: stepExecutor ? { stepExecutor } : undefined,
        approval: { expirationCheckInterval: 0, decisionClaimCheckInterval: 0 },
        eventWait: { expirationCheckInterval: 0, claimRecoveryCheckInterval: 0 },
    });
    return client.getExecutor();
}
export function getTenantFromEnv() {
    const projectSlug = getEnv("TENANT_PROJECT_SLUG");
    const token = getEnv("TENANT_TOKEN");
    const branch = getEnv("VERYFRONT_BRANCH_REF") || getEnv("TENANT_BRANCH_ID");
    const environmentName = getEnv("VERYFRONT_ENVIRONMENT_NAME") ||
        getEnv("TENANT_ENVIRONMENT_NAME");
    if (!projectSlug || !token) {
        return undefined;
    }
    return {
        projectSlug,
        token,
        projectId: getEnv("TENANT_PROJECT_ID"),
        productionMode: getEnv("TENANT_PRODUCTION_MODE") === "1",
        releaseId: getEnv("TENANT_RELEASE_ID"),
        ...(branch ? { branch } : {}),
        ...(environmentName ? { environmentName } : {}),
    };
}
/** Hydrate injected project env into the run context. Returns null when the run no longer exists. */
export async function hydrateRunContextEnv(backend, runId, run, expectedWorkerId) {
    const injectedEnv = mergeInjectedWorkflowEnv(run.context.env, getProcessEnv());
    if (!injectedEnv) {
        return run;
    }
    const currentSerialized = run.context.env ? JSON.stringify(run.context.env) : "";
    const nextSerialized = JSON.stringify(injectedEnv);
    if (currentSerialized === nextSerialized) {
        return run;
    }
    const outcome = await reconcileWorkflowRunControl({
        backend,
        operation: {
            type: "hydrate-env",
            run,
            env: injectedEnv,
            expectedWorkerId,
        },
    });
    if (outcome.run)
        return outcome.run;
    return await backend.getRun(runId);
}
export function getFinalRunExitCode(logger, exitCodes, runId, finalRun, debug = false) {
    const sanitizedRunId = sanitizeTerminalDiagnosticText(runId);
    switch (finalRun?.status) {
        case "completed":
            if (debug) {
                logger.info(`Workflow completed successfully: ${sanitizedRunId}`);
            }
            return exitCodes.SUCCESS;
        case "failed":
            logger.error(`Workflow failed: ${sanitizedRunId}`, finalRun.error);
            return exitCodes.WORKFLOW_FAILED;
        case "waiting":
            if (debug) {
                logger.info(`Workflow paused (waiting): ${sanitizedRunId}`);
            }
            return exitCodes.SUCCESS;
        case "cancelled":
            logger.warn(`Workflow was cancelled: ${sanitizedRunId}`);
            return exitCodes.WORKFLOW_FAILED;
        case "pending":
        case "running":
            logger.warn(`Workflow did not reach a durable final state: ${finalRun.status} (runId: ${sanitizedRunId})`);
            return exitCodes.WORKFLOW_FAILED;
        default:
            logger.warn(finalRun
                ? `Unexpected final status: ${finalRun.status} (runId: ${sanitizedRunId})`
                : `Workflow run was not found after execution: ${sanitizedRunId}`);
            return exitCodes.WORKFLOW_FAILED;
    }
}
export async function failRunExecution(backend, logger, exitCodes, runId, error, expectedWorkerId) {
    logger.error("Execution error:", error);
    await reconcileWorkflowRunControl({
        backend,
        operation: {
            type: "fail-execution",
            runId,
            error,
            expectedWorkerId,
        },
    });
    return exitCodes.WORKFLOW_FAILED;
}
export function runWithTenantContext(tenant, fn) {
    return runWithRequestContext({
        projectSlug: tenant.projectSlug,
        token: tenant.token,
        projectId: tenant.projectId,
        productionMode: tenant.productionMode,
        releaseId: tenant.releaseId,
        branch: tenant.branch,
        environmentName: tenant.environmentName,
    }, fn);
}
